package dao; import java.sql.*; import java.util.*; import negocio.*; public class ConvocatoriaComunidadDAOMySQL implements ConvocatoriaComunidadDAO { public void guardar(Connection c,ConvocatoriaComunidad v){v.validar();if(v.getId()<=0)insertar(c,v);else actualizar(c,v);} private void insertar(Connection c,ConvocatoriaComunidad v){String q="INSERT INTO comunidad_convocatorias(reserva_id,cliente_creador_id,perfil_creador_id,categoria_deportiva_id,posicion_buscada,participantes_confirmados,lugares_buscados,estado,clave_activa,comentario,motivo_cierre,fecha_publicacion,fecha_cierre,fecha_expiracion,version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)";try(PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){params(s,v);s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next())v.setId(r.getLong(1));}}catch(SQLException e){throw duplicado(e,"Ya existe una convocatoria activa para la reserva.");}} private void actualizar(Connection c,ConvocatoriaComunidad v){String q="UPDATE comunidad_convocatorias SET categoria_deportiva_id=?,posicion_buscada=?,participantes_confirmados=?,lugares_buscados=?,estado=?,clave_activa=?,comentario=?,motivo_cierre=?,fecha_publicacion=?,fecha_cierre=?,fecha_expiracion=?,version=version+1 WHERE id=? AND version=?";try(PreparedStatement s=c.prepareStatement(q)){int i=1;nullableLong(s,i++,v.getCategoriaDeportivaId());nullableString(s,i++,v.getPosicionBuscada()==null?null:v.getPosicionBuscada().name());s.setInt(i++,v.getParticipantesConfirmados());s.setInt(i++,v.getLugaresBuscados());s.setString(i++,v.getEstado().name());nullableInt(s,i++,v.getClaveActiva());s.setString(i++,v.getComentario());nullableString(s,i++,v.getMotivoCierre()==null?null:v.getMotivoCierre().name());nullableTime(s,i++,v.getFechaPublicacion());nullableTime(s,i++,v.getFechaCierre());nullableTime(s,i++,v.getFechaExpiracion());s.setLong(i++,v.getId());s.setLong(i,v.getVersion());if(s.executeUpdate()==0)throw new IllegalStateException("La convocatoria fue modificada por otra operación.");v.setVersion(v.getVersion()+1);}catch(SQLException e){throw duplicado(e,"Ya existe una convocatoria activa para la reserva.");}} private void params(PreparedStatement s,ConvocatoriaComunidad v)throws SQLException{int i=1;s.setLong(i++,v.getReservaId());s.setLong(i++,v.getClienteCreadorId());s.setLong(i++,v.getPerfilCreadorId());nullableLong(s,i++,v.getCategoriaDeportivaId());nullableString(s,i++,v.getPosicionBuscada()==null?null:v.getPosicionBuscada().name());s.setInt(i++,v.getParticipantesConfirmados());s.setInt(i++,v.getLugaresBuscados());s.setString(i++,v.getEstado().name());nullableInt(s,i++,v.getClaveActiva());s.setString(i++,v.getComentario());nullableString(s,i++,v.getMotivoCierre()==null?null:v.getMotivoCierre().name());nullableTime(s,i++,v.getFechaPublicacion());nullableTime(s,i++,v.getFechaCierre());nullableTime(s,i,v.getFechaExpiracion());} public ConvocatoriaComunidad buscar(Connection c,long id,boolean lock){return one(c," WHERE id=?"+(lock?" FOR UPDATE":""),id);} public ConvocatoriaComunidad buscarActivaPorReserva(Connection c,long id,boolean lock){return one(c," WHERE reserva_id=? AND clave_activa=1"+(lock?" FOR UPDATE":""),id);} public List<ConvocatoriaComunidad> listarPorCliente(Connection c,long id){return list(c," WHERE cliente_creador_id=? ORDER BY fecha_creacion DESC",id);} private ConvocatoriaComunidad one(Connection c,String w,long id){List<ConvocatoriaComunidad>x=list(c,w,id);return x.isEmpty()?null:x.getFirst();} private List<ConvocatoriaComunidad> list(Connection c,String w,long id){String q="SELECT * FROM comunidad_convocatorias"+w;try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){List<ConvocatoriaComunidad>o=new ArrayList<>();while(r.next())o.add(map(r));return o;}}catch(SQLException e){throw new RuntimeException("No se pudieron consultar las convocatorias.",e);}} private ConvocatoriaComunidad map(ResultSet r)throws SQLException{ConvocatoriaComunidad v=new ConvocatoriaComunidad();v.setId(r.getLong("id"));v.setReservaId(r.getLong("reserva_id"));v.setClienteCreadorId(r.getLong("cliente_creador_id"));v.setPerfilCreadorId(r.getLong("perfil_creador_id"));long x=r.getLong("categoria_deportiva_id");v.setCategoriaDeportivaId(r.wasNull()?null:x);String p=r.getString("posicion_buscada");if(p!=null)v.setPosicionBuscada(PosicionJugador.valueOf(p));v.setParticipantesConfirmados(r.getInt("participantes_confirmados"));v.setLugaresBuscados(r.getInt("lugares_buscados"));v.setEstado(EstadoConvocatoriaComunidad.valueOf(r.getString("estado")));v.setComentario(r.getString("comentario"));String m=r.getString("motivo_cierre");if(m!=null)v.setMotivoCierre(MotivoCierreConvocatoria.valueOf(m));v.setFechaPublicacion(time(r,"fecha_publicacion"));v.setFechaCierre(time(r,"fecha_cierre"));v.setFechaExpiracion(time(r,"fecha_expiracion"));v.setFechaCreacion(time(r,"fecha_creacion"));v.setFechaActualizacion(time(r,"fecha_actualizacion"));v.setVersion(r.getLong("version"));return v;} private RuntimeException duplicado(SQLException e,String m){return e.getErrorCode()==1062?new IllegalArgumentException(m,e):new RuntimeException("No se pudo guardar la convocatoria.",e);} private void nullableLong(PreparedStatement s,int i,Long v)throws SQLException{if(v==null)s.setNull(i,Types.BIGINT);else s.setLong(i,v);} private void nullableInt(PreparedStatement s,int i,Integer v)throws SQLException{if(v==null)s.setNull(i,Types.TINYINT);else s.setInt(i,v);} private void nullableString(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.VARCHAR);else s.setString(i,v);} private void nullableTime(PreparedStatement s,int i,java.time.LocalDateTime v)throws SQLException{if(v==null)s.setNull(i,Types.TIMESTAMP);else s.setTimestamp(i,Timestamp.valueOf(v));} private java.time.LocalDateTime time(ResultSet r,String c)throws SQLException{Timestamp t=r.getTimestamp(c);return t==null?null:t.toLocalDateTime();}}
